import sys
def compute_periods(n, s):
    def z_function(s):
        n = len(s)
        z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1
        return z

    periods = set()
    for fill in ['V', 'K']:
        filled_s = s.replace('?', fill)
        z = z_function(filled_s)
        for i in range(1, n):
            if i + z[i] == n and n % i == 0:
                periods.add(i)
    return sorted(periods)

input = sys.stdin.read().split('\n')
t = int(input[0])
results = []
index = 2
for _ in range(t):
    n = int(input[index])
    s = input[index + 1]
    periods = compute_periods(n, s)
    results.append(str(len(periods)))
    results.append(' '.join(map(str, periods)))
    index += 3
print('\n'.join(results))
